for name,quat in quats.items():
 t={'Gripper_Tip_R':[.67,-.25,.86]+quat}
 a=r.ik(t,seed=q,max_iters=500,tol_pos_m=.01,tol_rot_rad=.1)
 print(name,'ok',a['ok'],'err',a['error'])
