  pose=fk['poses']['Gripper_Tip_R']; b=r.ik({'Gripper_Tip_R':pose},seed=a['q'],max_iters=100,tol_pos_m=.001,tol_rot_rad=.001); print(' exact',b['ok'],b['error'])
